page_order = #{page.page_order}, page_type = #{page.page_type}, page_title = #{page.page_title}, page_content = #{page.page_content}, components = #{page.components}, page_version = page_version + 1, client_version = #{page.client_version}, autosave = #{page.autosave}, dirty = #{page.dirty}, last_saved_at = NOW(), updated_at = NOW()
WHERE id = #{page.id} AND page_version = #{expectedVersion}
